const readings = [21.5, 22.0, 21.8];
const avg = readings.reduce((a, b) => a + b, 0) / readings.length;
console.log('avg: ' + avg.toFixed(1));
console.log('status: ' + (avg > 25 ? 'ALERT' : 'OK'));

