const intervalMin = 15;
const capacityMah = 2000;
const perSendMah = 0.2;
const sendsPerDay = 1440 / intervalMin;
const days = Math.floor(capacityMah / (sendsPerDay * perSendMah));
console.log('sends per day: ' + sendsPerDay);
console.log('days of battery: ' + days);

